/*{
  "DESCRIPTION": "Curtains of aurora rippling slowly across the sky, bright at the base",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 1.0, 0.4, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.6, 0.1, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "folds", "TYPE": "float", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 4.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float t = mod(TIME * speed, 62.831853);
  float x = uv.x * folds;
  // The folds of the curtain: a slow large wave with a faster ripple over it. Whole tenths for
  // every frequency, so the twenty-pi wrap is seamless.
  float fold = 0.5 + 0.5 * sin(x * 1.9 + t * 0.7 + sin(x * 0.7 - t * 0.4) * 2.0);
  fold = fold * 0.65 + 0.35 * (0.5 + 0.5 * sin(x * 4.3 - t * 1.1));
  float y = isLine ? 0.3 : uv.y;
  // Brightest at the base, thinning towards the top of the sky.
  float base = 1.0 - smoothstep(0.0, 1.1, y);
  float lum = clamp(fold * 1.3 * (0.35 + base), 0.0, 1.0);
  // Green at the foot, violet higher up - two flat zones with a narrow edge, not a gradient.
  vec3 col = mix(colorA.rgb, colorB.rgb, smoothstep(0.42, 0.62, y + 0.15 * fold));
  gl_FragColor = vec4(col * (0.3 + 0.7 * lum), 1.0);
}

/*{
  "DESCRIPTION": "Red and white candy cane stripes spiralling steadily along the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.05, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripes", "TYPE": "float", "MIN": 2.0, "MAX": 12.0, "DEFAULT": 5.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // Wrapped so the scroll never loses precision; 100 * 0.5 is whole, so the wrap is seamless.
  float t = mod(TIME * speed, 100.0);
  // Diagonal on a matrix, straight along a line: the stripe still travels the same way.
  float d = isLine ? uv.x : (uv.x * aspect + uv.y) / (aspect + 1.0);
  float v = fract(d * stripes - t * 0.5);
  // 0 in the middle of a stripe, 1 at its edges; a pixel and a half of softening so neighbouring
  // bulbs on a roofline never sit at opposite brightness.
  float s = abs(v - 0.5) * 2.0;
  float aa = 1.5 * stripes / max(RENDERSIZE.x, 8.0);
  float band = smoothstep(0.5 + aa, 0.5 - aa, s);
  gl_FragColor = vec4(mix(colorB.rgb, colorA.rgb, band), 1.0);
}

/*{
  "DESCRIPTION": "Big bold checkerboard squares sliding steadily sideways",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.8, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "squares", "TYPE": "float", "MIN": 2.0, "MAX": 8.0, "DEFAULT": 4.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.5 is whole, so the slide never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  // Square squares: the count runs across the width, and the height gets as many as fit.
  float cx = uv.x * squares + t * 0.5;
  float cy = uv.y * squares / max(aspect, 0.25);
  float parity = mod(floor(cx) + floor(cy), 2.0);
  // A one-pixel dark seam between squares, so the board reads as squares and never blends two
  // palette colours through a muddy edge.
  float aaX = 1.2 * squares / max(RENDERSIZE.x, 8.0);
  float aaY = 1.2 * squares / max(aspect, 0.25) / max(RENDERSIZE.y, 8.0);
  float fx = fract(cx);
  float fy = fract(cy);
  float seam = smoothstep(0.0, aaX, fx) * smoothstep(1.0, 1.0 - aaX, fx) * smoothstep(0.0, aaY, fy) * smoothstep(1.0, 1.0 - aaY, fy);
  // On a line the seams would be dark bulbs between bright ones, so there the squares just butt.
  if (RENDERSIZE.y < 2.0) seam = 1.0;
  vec3 col = mix(colorA.rgb, colorB.rgb, parity);
  gl_FragColor = vec4(col * (0.15 + 0.85 * seam), 1.0);
}

/*{
  "DESCRIPTION": "The whole display washing slowly from one colour to the next, always bright",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.9, 0.2, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.1, 0.4, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "sweep", "TYPE": "float", "MIN": 0.0, "MAX": 0.5, "DEFAULT": 0.15 }
  ]
}*/
vec3 pick(float i) {
  if (i < 0.5) return colorA.rgb;
  if (i < 1.5) return colorB.rgb;
  return colorC.rgb;
}
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // 100 * 0.1 is whole, so the cycle never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  // The wash sweeps diagonally across the display rather than switching everywhere at once.
  float d = (uv.x * aspect + uv.y) / (aspect + 1.0);
  float phase = fract(t * 0.1 - d * sweep) * 3.0;
  float idx = floor(phase);
  float next = mod(idx + 1.0, 3.0);
  // Each colour holds for most of its third, then crosses to the next in a short, bright fade
  // rather than a long slide through the muddy midpoint.
  float k = smoothstep(0.8, 1.0, fract(phase));
  vec3 col = mix(pick(idx), pick(next), k);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A bright comet with a long glowing tail chasing itself around the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 0.4, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "tailLength", "TYPE": "float", "MIN": 0.2, "MAX": 0.9, "DEFAULT": 0.7 },
    { "NAME": "glow", "TYPE": "float", "MIN": 0.0, "MAX": 0.4, "DEFAULT": 0.22 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 20 pi: one orbit per 2 pi seconds at speed 1, and the wrap lands exactly on a whole orbit.
  float t = mod(TIME * speed, 62.831853);

  float back;   // how far behind the head this pixel is, 0..1 around the loop
  float onPath; // 1 on the comet's track, 0 off it
  float head;   // the bright head itself
  if (isLine) {
    float pos = fract(t / 6.2831853);
    back = fract(pos - uv.x);
    onPath = 1.0;
    head = smoothstep(0.06, 0.0, abs(uv.x - pos));
  } else {
    float r = length(p);
    float radius = 0.34 * min(aspect, 1.0);
    float a = atan(p.y, p.x);
    back = fract((t - a) / 6.2831853);
    onPath = smoothstep(0.14, 0.04, abs(r - radius));
    vec2 headPos = vec2(cos(t), sin(t)) * radius;
    head = smoothstep(0.13, 0.0, length(p - headPos));
  }
  // The tail is what moves: it is a function of the head's position, so it reaches the output.
  float tail = pow(clamp(1.0 - back / tailLength, 0.0, 1.0), 2.2) * onPath;
  vec3 col = colorA.rgb * (tail + glow);
  col = mix(col, colorB.rgb, head);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Bright rings expanding outward from the centre one after another",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.1, 0.4, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "count", "TYPE": "float", "MIN": 1.0, "MAX": 8.0, "DEFAULT": 3.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // Centred and aspect-corrected: a ring is a ring on a wide panel, and on a line it is a pair
  // of pulses running out from the middle.
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  float t = mod(TIME * speed, 100.0);
  // A line is one pixel tall, so its "radius" is just the distance from the middle of it.
  float d = RENDERSIZE.y < 2.0 ? abs(uv.x - 0.5) * 2.0 : length(p);
  // The wave itself is what moves. 100 * 0.5 is whole, so the wrap is seamless.
  float ring = fract(d * count - t * 0.5);
  // Softer on a line, where the ring is bulbs in a row and a hard edge is a flicker.
  float aa = (RENDERSIZE.y < 2.0 ? 3.0 : 1.5) * count / max(RENDERSIZE.x, 8.0);
  float band = smoothstep(0.55 + aa, 0.55 - aa, ring) * smoothstep(0.1 - aa, 0.1 + aa, ring);
  // Alternate rings take alternate palette colours, flat, never mixed through a midpoint.
  float which = step(0.5, fract((d * count - t * 0.5) * 0.5));
  vec3 col = mix(colorA.rgb, colorB.rgb, which);
  // Fade with distance so the newest ring is the brightest, but never below what reads at night.
  float fade = 0.6 + 0.4 * (1.0 - smoothstep(0.0, 0.75, d));
  gl_FragColor = vec4(col * band * fade, 1.0);
}

/*{
  "DESCRIPTION": "The warm restless flicker of firelight in deep orange and gold",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.25, 0.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.8, 0.15, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "height", "TYPE": "float", "MIN": 0.4, "MAX": 1.5, "DEFAULT": 0.9 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float t = mod(TIME * speed, 62.831853);
  // Sums of sines rather than a hash: every frequency is a whole number of tenths, so the
  // twenty-pi wrap is seamless and nothing ever loses precision.
  float x = uv.x * 6.0;
  float y = isLine ? 0.5 : uv.y;
  float n = sin(x * 1.3 + t * 1.7) * 0.5 + sin(x * 2.9 - t * 2.3 + y * 4.0) * 0.3 + sin(y * 7.0 - t * 3.1 + x * 0.7) * 0.4;
  n = 0.5 + 0.5 * n / 1.2;
  // Hot at the bottom, dying out towards the top; on a line the whole strip is the fire's base.
  float rise = isLine ? 0.65 : clamp(1.0 - uv.y / height, 0.0, 1.0);
  float heat = clamp(rise * (0.55 + 0.9 * n), 0.0, 1.0);
  // Never dim enough to read as off: the coals always glow.
  float lit = 0.35 + 0.65 * smoothstep(0.1, 0.8, heat);
  vec3 col = mix(colorA.rgb, colorB.rgb, smoothstep(0.55, 0.85, heat));
  gl_FragColor = vec4(col * lit, 1.0);
}

/*{
  "DESCRIPTION": "A red white and blue flag rippling in a steady breeze",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.05, 0.05, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.05, 0.15, 1.0, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "stripes", "TYPE": "float", "MIN": 3.0, "MAX": 13.0, "DEFAULT": 7.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float t = mod(TIME * speed, 62.831853);
  // The breeze: a wave travelling along the flag, and the cloth's shading follows its slope.
  float phase = uv.x * 8.0 - t * 2.0;
  float wave = sin(phase);
  float shade = 0.72 + 0.28 * cos(phase + 0.8);
  vec3 col;
  if (isLine) {
    // A line shows the stripes running along it, carried by the same breeze.
    float s = mod(floor(fract(uv.x - t * 0.05) * stripes), 2.0);
    col = mix(colorA.rgb, colorB.rgb, s);
  } else {
    float yy = uv.y + 0.035 * wave;
    float s = mod(floor(clamp(yy, 0.0, 0.999) * stripes), 2.0);
    col = mix(colorA.rgb, colorB.rgb, s);
    // The canton, top left, with a few stars in it.
    if (uv.x < 0.42 && yy > 0.53) {
      vec2 cell = floor(vec2(uv.x / 0.42, (yy - 0.53) / 0.47) * vec2(4.0, 3.0));
      vec2 local = fract(vec2(uv.x / 0.42, (yy - 0.53) / 0.47) * vec2(4.0, 3.0)) - 0.5;
      float star = smoothstep(0.22, 0.1, length(local)) * step(0.5, mod(cell.x + cell.y + 1.0, 2.0));
      col = mix(colorC.rgb, colorB.rgb, star);
    }
  }
  gl_FragColor = vec4(col * shade, 1.0);
}

/*{
  "DESCRIPTION": "A deep red heartbeat pulsing twice then resting, over and over",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.05, 0.1, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "rest", "TYPE": "float", "MIN": 0.1, "MAX": 0.6, "DEFAULT": 0.5 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 100 * 0.5 is whole: one beat cycle every two seconds at speed 1, wrapping cleanly.
  // Offset so the very first frame lands on a beat rather than on the rest.
  float phase = fract(mod(TIME * speed, 100.0) * 0.5 + 0.12);
  // Two beats close together, the second a little softer, then the rest of the cycle quiet.
  float b1 = pow(max(0.0, 1.0 - abs(phase - 0.12) * 9.0), 2.0);
  float b2 = pow(max(0.0, 1.0 - abs(phase - 0.32) * 9.0), 2.0) * 0.8;
  float beat = max(b1, b2);
  // The resting glow is what keeps it from ever reading as off.
  float env = rest + (1.0 - rest) * beat;
  // Brighter at the centre, and the beat swells outward.
  float d = isLine ? abs(uv.x - 0.5) * 2.0 : length(p) / 0.72;
  float swell = 1.0 - smoothstep(0.0, 1.0, d) * (0.5 - 0.3 * beat);
  gl_FragColor = vec4(colorA.rgb * env * swell, 1.0);
}

/*{
  "DESCRIPTION": "Theatre marquee bulbs chasing around the edge of the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.3, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "spacing", "TYPE": "float", "MIN": 2.0, "MAX": 6.0, "DEFAULT": 3.0 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  vec2 px = uv * RENDERSIZE;
  float w = RENDERSIZE.x;
  float h = RENDERSIZE.y;
  // 100 * 3 is a multiple of the three-bulb cycle, so the chase never skips at the wrap.
  float t = mod(TIME * speed, 100.0);
  float stepIndex = floor(t * 3.0);
  // Position along the edge, going round clockwise from the bottom-left corner. On a line the
  // whole strip is the edge.
  float bw = 1.5;
  float s = -1.0;
  if (isLine) s = px.x;
  else if (px.y < bw) s = px.x;
  else if (px.x > w - bw) s = w + px.y;
  else if (px.y > h - bw) s = w + h + (w - px.x);
  else if (px.x < bw) s = 2.0 * w + h + (h - px.y);
  vec3 col;
  if (s >= 0.0) {
    // Every third bulb lit, and the lit one steps along three times a second. Each lit bulb is
    // a soft glow rather than a hard dot, so neighbouring bulbs never sit at opposite brightness.
    float u = mod(s / spacing - stepIndex, 3.0);
    float dist = min(abs(u - 0.5), 3.0 - abs(u - 0.5));
    float lit = smoothstep(1.4, 0.2, dist);
    col = mix(colorA.rgb * 0.22, colorA.rgb, lit);
  } else {
    // Inside the frame: the sign itself, breathing slowly in the second colour.
    float breathe = 0.55 + 0.25 * sin(mod(TIME * speed, 62.831853) * 0.5);
    vec2 q = (uv - 0.5) * 2.0;
    float inner = 1.0 - smoothstep(0.5, 1.0, max(abs(q.x), abs(q.y)));
    col = colorB.rgb * breathe * (0.55 + 0.45 * inner);
  }
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Big soft blobs drifting and merging into each other like a lava lamp",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.5, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.85, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "size", "TYPE": "float", "MIN": 0.1, "MAX": 0.5, "DEFAULT": 0.22 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  // Capped so a 60-wide line is a few units across, not sixty.
  float ax = min(aspect, 3.0);
  vec2 p = (uv - 0.5) * vec2(ax, 1.0);
  float t = mod(TIME * speed, 62.831853);
  // Four blobs on their own slow figures; every frequency is a whole tenth so the wrap is clean.
  vec2 b0 = vec2(sin(t * 0.6), cos(t * 0.8)) * 0.3;
  vec2 b1 = vec2(cos(t * 1.0 + 1.0), sin(t * 0.4 + 2.0)) * 0.32;
  vec2 b2 = vec2(sin(t * 0.8 + 3.0), sin(t * 1.2 + 1.0)) * 0.28;
  vec2 b3 = vec2(cos(t * 0.4 + 2.0), cos(t * 1.0)) * 0.3;
  if (isLine) {
    // On a line the blobs sit on it: only their x matters, or they would miss it entirely.
    b0.y = 0.0; b1.y = 0.0; b2.y = 0.0; b3.y = 0.0;
    b0.x *= ax; b1.x *= ax; b2.x *= ax; b3.x *= ax;
  }
  float s = size * size;
  float field = s / max(dot(p - b0, p - b0), 0.0004)
              + s / max(dot(p - b1, p - b1), 0.0004)
              + s / max(dot(p - b2, p - b2), 0.0004)
              + s / max(dot(p - b3, p - b3), 0.0004);
  // Three flat zones - dark, body, hot core - with narrow edges so no two colours ever mix into mud.
  float body = smoothstep(0.85, 1.15, field);
  float core = smoothstep(2.4, 3.2, field);
  vec3 col = colorA.rgb * body;
  col = mix(col, colorB.rgb, core);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Blocks of colour cascading down the display in columns at different speeds",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [0.1, 0.5, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.2, 0.6, 1.0] },
    { "NAME": "colorC", "TYPE": "color", "DEFAULT": [0.2, 1.0, 0.4, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "columnWidth", "TYPE": "float", "MIN": 2.0, "MAX": 8.0, "DEFAULT": 4.0 }
  ]
}*/
float hash(vec2 c) {
  return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}
vec3 pick(float i) {
  if (i < 0.5) return colorA.rgb;
  if (i < 1.5) return colorB.rgb;
  return colorC.rgb;
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  // On a line the blocks run along it: swap the axes and the same code runs.
  vec2 size = isLine ? RENDERSIZE.yx : RENDERSIZE;
  vec2 px = (isLine ? uv.yx : uv) * size;
  // 100 * 0.1 is whole, so every fall rate below wraps seamlessly.
  float t = mod(TIME * speed, 100.0);
  float col = floor(px.x / columnWidth);
  // A dim base in the column's colour, so the display is never empty between blocks.
  vec3 out3 = pick(mod(col, 3.0)) * 0.16;
  // Two blocks per column, half a cycle apart, so a column is never empty for long.
  for (int i = 0; i < 2; i++) {
    float fi = float(i);
    float h = hash(vec2(col, fi));
    float rate = 0.1 + 0.1 * floor(hash(vec2(col + 3.0, fi)) * 4.0);
    float y = fract(h + fi * 0.5 - t * rate);
    // The block's head, and a trail of the same colour fading behind it upward.
    float head = y * size.y;
    float len = 0.4 * size.y;
    float behind = px.y - head;
    float body = step(0.0, behind) * step(behind, len) * (1.0 - smoothstep(0.0, len, behind) * 0.8);
    vec3 c = pick(mod(col + fi, 3.0));
    out3 = max(out3, c * body);
  }
  gl_FragColor = vec4(out3, 1.0);
}

