  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 20 pi: one revolution per 2 pi seconds at speed 1, wrapping on a whole turn.
  float t = mod(TIME * speed, 62.831853);
  float back;
  float edge;
  if (isLine) {
    // A line can't turn, so the sweep runs along it and starts again.
    float pos = fract(t / 6.2831853);
    back = fract(pos - uv.x);
    edge = smoothstep(0.05, 0.0, abs(uv.x - pos));
  } else {
    float a = atan(p.y, p.x);
    back = fract((t - a) / 6.2831853);
    edge = smoothstep(0.07, 0.0, min(back, 1.0 - back));
  }
  // The trail: bright just behind the line, fading round to nothing before the line comes back.
  float glow = pow(clamp(1.0 - back / trail, 0.0, 1.0), 2.5);
  // Faint range rings under everything, so the screen reads as a radar and not just a wedge.
  float r = length(p);
  float rings = isLine ? 0.0 : smoothstep(0.07, 0.0, abs(fract(r * 3.0 + 0.5) - 0.5)) * 0.35;
  vec3 col = colorA.rgb * (0.16 + rings + glow);
  col = mix(col, colorB.rgb, edge * 0.85);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A smooth saturated rainbow sweeping steadily across the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "bands", "TYPE": "float", "MIN": 0.5, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "diagonal", "TYPE": "bool", "DEFAULT": true }
  ]
}*/
vec3 hsv2rgb(vec3 c) {
  vec3 p = abs(fract(c.xxx + vec3(0.0, 2.0 / 3.0, 1.0 / 3.0)) * 6.0 - 3.0);
  return c.z * mix(vec3(1.0), clamp(p - 1.0, 0.0, 1.0), c.y);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  float t = mod(TIME * speed, 100.0);
  float d = (isLine || !diagonal) ? uv.x : (uv.x * aspect + uv.y) / (aspect + 1.0);
  // 100 * 0.25 is whole, so the hue never jumps when the clock wraps.
  float hue = fract(d * bands - t * 0.25);
  gl_FragColor = vec4(hsv2rgb(vec3(hue, 1.0, 1.0)), 1.0);
}

/*{
  "DESCRIPTION": "Big soft snowflakes drifting gently down against a deep winter sky",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 1.0, 1.0, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [0.05, 0.12, 0.6, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "flakeSize", "TYPE": "float", "MIN": 1.0, "MAX": 4.0, "DEFAULT": 1.8 },
    { "NAME": "sky", "TYPE": "float", "MIN": 0.1, "MAX": 0.8, "DEFAULT": 0.35 }
  ]
}*/
float hash(vec2 c) {
  return fract(sin(dot(c, vec2(127.1, 311.7))) * 43758.5453);
}
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  // On a line there is no "down", so the flakes drift along it instead: swap the axes and the
  // same code runs, columns become the one row and the fall runs left to right.
  vec2 size = isLine ? RENDERSIZE.yx : RENDERSIZE;
  vec2 px = (isLine ? uv.yx : uv) * size;
  // 100 * 0.1 is whole, so every fall rate below wraps seamlessly.
  float t = mod(TIME * speed, 100.0);
  // Flakes scale with the canvas: a flake is a bulb or two on a matrix, and a proper blob on a
  // screen-sized panel rather than a speck.
  float scale = max(1.0, min(size.x, size.y) / 32.0);
  float colW = 4.0 * scale;
  float cols = max(1.0, floor(size.x / colW));
  float snow = 0.0;
  // Three layers of flakes, each column with its own speed and offset, so it never looks like
  // a repeating pattern.
  for (int layer = 0; layer < 2; layer++) {
    float fl = float(layer);
    float c = floor(px.x / (size.x / cols));
    float h = hash(vec2(c, fl));
    float h2 = hash(vec2(c + 7.0, fl + 3.0));
    float rate = 0.1 + 0.1 * floor(h2 * 3.0);
    // Falling: the y position decreases with time. Each layer is offset a third of the way.
    // Not every column carries a flake in every layer, or it reads as static rather than snow.
    if (hash(vec2(c + 11.0, fl)) < 0.3) continue;
    float fy = fract(h + fl / 2.0 - t * rate);
    float cx = (c + 0.5) * (size.x / cols) + sin(fy * 12.566 + h * 6.28) * 0.6;
    float cy = fy * size.y;
    float d = length(px - vec2(cx, cy));
    snow = max(snow, smoothstep(flakeSize * scale, flakeSize * scale * 0.25, d));
  }
  vec3 col = colorB.rgb * sky;
  col = mix(col, colorA.rgb, snow);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "A spiral tunnel turning slowly, pulling the eye into the middle of the display",
  "CREDIT": "webXLights",
  "CATEGORIES": ["Generator"],
  "INPUTS": [
    { "NAME": "colorA", "TYPE": "color", "DEFAULT": [1.0, 0.1, 0.1, 1.0] },
    { "NAME": "colorB", "TYPE": "color", "DEFAULT": [1.0, 0.9, 0.2, 1.0] },
    { "NAME": "speed", "TYPE": "float", "MIN": 0.1, "MAX": 4.0, "DEFAULT": 1.0 },
    { "NAME": "arms", "TYPE": "float", "MIN": 1.0, "MAX": 4.0, "DEFAULT": 2.0 },
    { "NAME": "twist", "TYPE": "float", "MIN": 0.5, "MAX": 3.0, "DEFAULT": 1.4 }
  ]
}*/
void main() {
  vec2 uv = isf_FragNormCoord;
  bool isLine = RENDERSIZE.y < 2.0;
  float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);
  vec2 p = (uv - 0.5) * vec2(aspect, 1.0);
  // 100 * 0.3 is whole, so the turn never jumps when the clock wraps.
  float t = mod(TIME * speed, 100.0);
  float s;
  if (isLine) {
    // A line can't spiral, so the bands run in from both ends towards the middle instead.
    s = fract(abs(uv.x - 0.5) * 2.0 * arms + t * 0.3);
  } else {
    float r = length(p);
    float a = atan(p.y, p.x) / 6.2831853;
    // Angle plus log-radius is a spiral; adding time turns it and draws it inward.
    s = fract(a * arms + log(r + 0.03) * twist + t * 0.3);
  }
  float aa = (isLine ? 4.0 : 2.0) * arms / max(RENDERSIZE.x, 8.0);
  float band = smoothstep(0.5 + aa, 0.5 - aa, abs(s - 0.5) * 2.0);
  // The dark half of each arm is not black: a dim version of the other colour keeps the whole
  // tunnel readable while the bright arm carries the spin.
  vec3 col = mix(colorB.rgb * 0.22, colorA.rgb, band);
  // The centre glows, which is what makes it a tunnel rather than a pinwheel.
  float centre = isLine ? 0.0 : smoothstep(0.22, 0.0, length(p));
  col = mix(col, colorB.rgb, centre);
  gl_FragColor = vec4(col, 1.0);
}

/*{
  "DESCRIPTION": "Bright rays bursting outward from the centre and fading, one burst after another",
  "CREDIT": "webXLights",
